/* 固定ヘッダーの高さぶん、スクロール時の余白を確保する */
html {
  scroll-padding-top: 5rem;     /* 固定ヘッダーの高さに合わせる */
  scroll-padding-bottom: 4rem;  /* 固定フッターがある場合 */
}

/* フォーカス表示は常に見えるようにする */
:focus-visible {
  outline: 3px solid #1a5fb4;
  outline-offset: 2px;
}

/* アイコンボタンの最小サイズを確保 */
.icon-button {
  min-inline-size: 24px;
  min-block-size: 24px;
  padding: 8px;               /* 実際のタップ領域は広めに取るのが推奨 */
}

