originalCss:
:root {
    --bg: #07111e;
    --panel: #0d1b2e;
    --panel2: #12233b;
    --line: #22385a;
    --accent: #7c9eff;
    --text: #e6edf8;
    --text-dim: #c7d6ec;
    --text-faint: #9cb0cf;
    --ok: #5ee0a0;
    --warn: #ffcf70;
    --sb: 288px;
}
* {
    box-sizing: border-box;
}
html {
    scroll-behavior: smooth;
    overflow-x: hidden;
}
body {
    margin: 0;
    background: var(--bg);
    color: var(--text);
    font-family:
        'Noto Sans JP',
        -apple-system,
        'Hiragino Kaku Gothic ProN',
        'Yu Gothic',
        Meiryo,
        sans-serif;
    font-size: 16px;
    line-height: 1.85;
    overflow-x: hidden;
}
.sidebar {
    position: fixed;
    top: 0;
    left: 0;
    bottom: 0;
    width: var(--sb);
    background: #091526;
    border-right: 1px solid var(--line);
    overflow-y: auto;
    padding: 22px 16px 40px;
    z-index: 30;
}
.sb-title {
    font-size: 13px;
    font-weight: 800;
    color: var(--accent);
    letter-spacing: 0.04em;
    margin: 0 0 14px;
    line-height: 1.5;
}
.sidebar a {
    display: block;
    color: var(--text-dim);
    text-decoration: none;
    font-size: 13.5px;
    line-height: 1.5;
    padding: 6px 10px;
    border-radius: 8px;
    border-left: 3px solid transparent;
}
.sidebar a:hover {
    background: #10223a;
    color: #fff;
}
.sidebar a.active {
    background: #14294a;
    color: #fff;
    border-left-color: var(--accent);
}
.nav-h2 {
    font-weight: 700;
    margin-top: 8px;
}
.nav-sub {
    list-style: none;
    margin: 0 0 4px 8px;
    padding: 0;
}
.nav-sub a {
    font-size: 12.5px;
    color: var(--text-faint);
}
.toggle {
    display: none;
    position: fixed;
    top: 12px;
    left: 12px;
    z-index: 40;
    background: var(--panel2);
    color: var(--text);
    border: 1px solid var(--line);
    border-radius: 10px;
    padding: 8px 12px;
    font: inherit;
    font-size: 14px;
    cursor: pointer;
}
.main {
    margin-left: var(--sb);
    padding: 40px 48px 80px;
}
.hero {
    position: relative;
    background: linear-gradient(180deg, #0e1f38, #0a1729);
    border: 1px solid var(--line);
    border-radius: 18px;
    padding: 34px 36px;
    margin-bottom: 36px;
    overflow: hidden;
}
.hero::before {
    content: '';
    position: absolute;
    top: -120px;
    right: -80px;
    width: 360px;
    height: 360px;
    background: radial-gradient(circle, rgba(124, 158, 255, 0.28), transparent 65%);
    pointer-events: none;
}
.badge {
    display: inline-block;
    font-size: 12px;
    font-weight: 700;
    color: var(--accent);
    background: rgba(124, 158, 255, 0.12);
    border: 1px solid rgba(124, 158, 255, 0.4);
    padding: 3px 12px;
    border-radius: 999px;
    margin-bottom: 14px;
    letter-spacing: 0.05em;
}
.hero-title {
    font-size: 28px;
    font-weight: 800;
    color: #fff;
    line-height: 1.4;
    margin: 0 0 20px;
}
.meta {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 16px 32px;
    position: relative;
}
.meta-item {
    display: flex;
    flex-direction: column;
    min-width: 0;
    padding-left: 14px;
    border-left: 2px solid var(--line);
}
.meta-item:first-child {
    grid-column: 1/-1;
}
.meta-label {
    font-size: 11px;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--text-faint);
}
.meta-value {
    font-size: 14.5px;
    color: var(--text);
    overflow-wrap: anywhere;
}
.main h2 {
    font-size: 24px;
    font-weight: 800;
    color: #fff;
    margin: 56px 0 18px;
    padding-bottom: 10px;
    border-bottom: 1px solid var(--line);
    scroll-margin-top: 20px;
}
.main h3 {
    font-size: 19px;
    font-weight: 700;
    color: #dfe9ff;
    margin: 34px 0 12px;
    scroll-margin-top: 20px;
}
.main h3::before {
    content: '';
    display: inline-block;
    width: 4px;
    height: 1em;
    background: var(--accent);
    border-radius: 2px;
    margin-right: 10px;
    vertical-align: -2px;
}
.main p {
    color: var(--text-dim);
    margin: 12px 0;
}
.main li {
    color: var(--text-dim);
    margin: 4px 0;
}
.main strong {
    color: #fff;
}
.main a {
    color: var(--accent);
    overflow-wrap: anywhere;
}
.main code:not(pre code) {
    font-family: 'JetBrains Mono', ui-monospace, monospace;
    font-size: 0.88em;
    background: #12233b;
    border: 1px solid var(--line);
    padding: 1px 6px;
    border-radius: 5px;
    color: #bcd0ff;
    overflow-wrap: anywhere;
}
.main pre {
    background: #050d18;
    border: 1px solid var(--line);
    border-radius: 12px;
    padding: 16px 18px;
    overflow-x: auto;
    line-height: 1.6;
}
.main pre code {
    font-family: 'JetBrains Mono', ui-monospace, monospace;
    font-size: 13.5px;
    color: #d5e2fa;
    background: none;
    border: 0;
    padding: 0;
    white-space: pre;
}
.callout {
    margin: 18px 0;
    padding: 14px 18px;
    background: rgba(124, 158, 255, 0.08);
    border: 1px solid rgba(124, 158, 255, 0.3);
    border-left: 4px solid var(--accent);
    border-radius: 10px;
}
.callout p {
    margin: 6px 0;
}
.table-scroll {
    overflow-x: auto;
    margin: 16px 0;
    border: 1px solid var(--line);
    border-radius: 12px;
    background: var(--panel);
}
.main table {
    border-collapse: collapse;
    width: 100%;
    font-size: 14.5px;
    min-width: 560px;
}
.main th {
    background: #13264a;
    color: #fff;
    text-align: left;
    font-weight: 700;
    padding: 10px 14px;
    border-bottom: 1px solid var(--line);
    white-space: nowrap;
}
.main td {
    padding: 10px 14px;
    border-bottom: 1px solid #182c4a;
    color: var(--text-dim);
    vertical-align: top;
}
.main tr:last-child td {
    border-bottom: none;
}
.main tr:nth-child(even) td {
    background: rgba(255, 255, 255, 0.015);
}
.mermaid-diagram {
    display: block;
    overflow-x: auto;
    margin: 20px 0;
    padding: 22px 18px;
    background: var(--panel);
    border: 1px solid var(--line);
    border-radius: 14px;
}
.mermaid-diagram svg {
    display: block;
    margin-left: auto;
    margin-right: auto;
    max-width: none;
    flex-shrink: 0;
}
.mermaid-diagram foreignObject {
    overflow: visible;
}
.mermaid-diagram foreignObject div,
.mermaid-diagram foreignObject span,
.mermaid-diagram foreignObject p {
    white-space: normal !important;
}
.main .mermaid-diagram p {
    color: inherit;
    margin: 0;
}
.checklist-card {
    background: var(--panel);
    border: 1px solid var(--line);
    border-radius: 14px;
    padding: 18px 20px;
    margin: 18px 0;
}
.checklist-card ul {
    list-style: none;
    margin: 0;
    padding: 0;
}
.checklist-card li {
    padding: 8px 0;
    border-bottom: 1px solid #182c4a;
    display: flex;
    gap: 10px;
    align-items: flex-start;
}
.checklist-card li:last-child {
    border-bottom: none;
}
.checklist-card input {
    margin-top: 7px;
    accent-color: var(--accent);
    width: 16px;
    height: 16px;
    flex: none;
}
.checklist-progress {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 10px;
}
.cp-label {
    font-weight: 700;
    color: #fff;
    font-size: 14px;
    white-space: nowrap;
}
.cp-bar {
    flex: 1;
    height: 8px;
    background: #0a1830;
    border-radius: 99px;
    overflow: hidden;
}
.cp-fill {
    height: 100%;
    width: 0;
    background: linear-gradient(90deg, var(--accent), var(--ok));
    transition: width 0.25s;
}
.cp-count {
    font-size: 13px;
    color: var(--text-faint);
    font-variant-numeric: tabular-nums;
}
.page-footer {
    margin-top: 60px;
    padding-top: 20px;
    border-top: 1px solid var(--line);
    color: var(--text-faint);
    font-size: 13.5px;
}
@media (max-width: 900px) {
    .sidebar {
        transform: translateX(-100%);
        transition: transform 0.2s;
    }
    .sidebar.open {
        transform: none;
    }
    .toggle {
        display: block;
    }
    .main {
        margin-left: 0;
        padding: 64px 18px 60px;
    }
    .hero {
        padding: 24px 20px;
    }
    .hero-title {
        font-size: 23px;
    }
    .meta {
        grid-template-columns: 1fr;
    }
}
